// ─── File: src/main/java/com/bank/fraud/service/TransactionHistoryService.java ───
// *** THIS IS THE KEY CLASS THAT BREAKS THE CIRCULAR DEPENDENCY ***
// Before: TransferService ↔ FraudCheckService (circular)
// After:  TransferService → FraudCheckService → TransactionHistoryService ← TransferService
//         Both depend on HistoryService independently. No cycle.

package com.bank.fraud.service;

import com.bank.fraud.model.TransferRecord;
import com.bank.fraud.repository.TransactionHistoryRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class TransactionHistoryService {

    private final TransactionHistoryRepository historyRepo;

    public void recordTransfer(String fromId, String toId, BigDecimal amount) {
        TransferRecord record = new TransferRecord(fromId, toId, amount);
        historyRepo.save(record);
        log.info("Transfer recorded: {} → {} Rs.{}", fromId, toId, amount);
    }

    public List<TransferRecord> getRecentTransfers(String accountId, int hoursBack) {
        LocalDateTime since = LocalDateTime.now().minusHours(hoursBack);
        return historyRepo.findRecentByAccount(accountId, since);
    }

    public long countRecentTransfers(String accountId, int hoursBack) {
        LocalDateTime since = LocalDateTime.now().minusHours(hoursBack);
        return historyRepo.countByFromAccountIdAndCreatedAtAfter(accountId, since);
    }
}
