package com.bank.fraud.service;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
@Slf4j
public class FraudCheckService {

    // Depends on TransactionHistoryService — NOT on TransferService (no cycle!)
    private final TransactionHistoryService historyService;

    @Value("${fraud.max-transfers-per-hour:5}")
    private int maxTransfersPerHour;

    @Value("${fraud.high-value-threshold:500000}")
    private int highValueThreshold;

    /**
     * Checks if a transfer is safe based on velocity and amount.
     * Uses TransactionHistoryService for pattern analysis — NOT TransferService.
     */
    public boolean isSafeTransfer(String fromAccountId, BigDecimal amount) {
        // Check 1: velocity — too many transfers in last hour?
        long recentCount = historyService.countRecentTransfers(fromAccountId, 1);
        if (recentCount >= maxTransfersPerHour) {
            log.warn("FRAUD ALERT: {} has {} transfers in last hour (max={})",
                fromAccountId, recentCount, maxTransfersPerHour);
            return false;
        }

        // Check 2: high value — flag for review
        if (amount.compareTo(BigDecimal.valueOf(highValueThreshold)) > 0) {
            log.warn("HIGH VALUE: Rs.{} from {} — flagged for review", amount, fromAccountId);
            // Still allow but flag — could be legitimate
        }

        log.info("Fraud check PASSED for {} (recent transfers: {})", fromAccountId, recentCount);
        return true;
    }
}
