package com.bank.fraud.service;

import com.bank.fraud.dto.TransferRequest;
import com.bank.fraud.event.TransferCompletedEvent;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.context.ApplicationEventPublisher;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class TransferServiceTest {

    @Mock FraudCheckService fraudCheckService;
    @Mock TransactionHistoryService historyService;
    @Mock ApplicationEventPublisher eventPublisher;
    @InjectMocks TransferService transferService;

    @Test
    void shouldCompleteTransferWhenFraudCheckPasses() {
        when(fraudCheckService.isSafeTransfer("SAV2001", new BigDecimal("50000")))
            .thenReturn(true);

        String result = transferService.transfer(
            new TransferRequest("SAV2001", "CUR3001", new BigDecimal("50000")));

        assertThat(result).isEqualTo("COMPLETED");
        verify(historyService).recordTransfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        verify(eventPublisher).publishEvent(any(TransferCompletedEvent.class));
    }

    @Test
    void shouldRejectTransferWhenFraudCheckFails() {
        when(fraudCheckService.isSafeTransfer("SAV2001", new BigDecimal("50000")))
            .thenReturn(false);

        String result = transferService.transfer(
            new TransferRequest("SAV2001", "CUR3001", new BigDecimal("50000")));

        assertThat(result).isEqualTo("REJECTED");
        verify(historyService, never()).recordTransfer(any(), any(), any());
    }
}
